'use strict';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state={done:new Set(),drafts:{},fb:{},answers:{},quiz:[],qi:0,part:1,game:'match',match:{},device:{},sequence:[2,0,3,1],checks:{},saved:true};
const wc=v=>v.trim()?v.trim().split(/\s+/).length:0;
const head=(n,t,p='')=>`<div class="eyebrow">${n}</div><h1>${t}</h1>${p?`<p class="lead">${p}</p>`:''}`;
const box=id=>`<div id="fb-${id}" class="feedback" role="status" aria-live="polite">${state.fb[id]||''}</div>`;
const field=(id,label,ph='Ойыңды мәтіндегі дәлелмен негізде...',rows=5)=>`<label for="${id}">${label}</label><textarea id="${id}" data-draft="${id}" rows="${rows}" placeholder="${ph}">${esc(state.drafts[id]||'')}</textarea>`;
function fb(id,html,error=false){state.fb[id]=html;const el=$('#fb-'+id);if(el){el.innerHTML=html;el.classList.toggle('error',error);}return html;}
const link=(prefix,label='Мәтіндегі эпизодқа оралу')=>`<a class="text-link" href="#read/${BOOK.paragraphs.findIndex(p=>p.includes(prefix))}">${label} ↗</a>`;
const idea=()=>`<div class="unit-idea"><span class="tiny">ЗЕРТТЕУ ИДЕЯСЫ</span><p>${IDEA}</p></div>`;
const list=()=>`<div class="lesson-list">${lessons.map((l,i)=>`<a class="lesson-row" href="#lessons/${i}"><span class="number">0${i+1}</span><div><h3>${l.title}</h3><p>${l.sub}</p></div><span class="arrow">${state.done.has(i)?'✓':'↗'}</span></a>`).join('')}</div>`;
function home(){return head('9-СЫНЫП · ҚАЗАҚ ӘДЕБИЕТІ','Тәрбие мен<br><em>салт дәстүр</em>')+`<div class="hero"><div><p class="lead">Бір ұядан басталған өмір. Бірнеше ұрпақтың өнегесі. Бауыржанның естеліктерінен адам мінезі мен көзқарасының қалыптасуын зертте.</p><div class="actions"><a class="button" href="#lessons/0">Алғашқы сабақты бастау →</a><a class="button secondary" href="#read">Шығарманы оқу</a></div>${idea()}</div><div class="focus-card"><small>ЮНИТ СОҢЫНДАҒЫ МАҚСАТ</small><div class="big">А + Д</div><h3>Үзіндіні өзің талда</h3><p>Тұжырым жаса. Дәйексөз келтір. Автор таңдауының әсерін түсіндір.</p><a class="button light" href="#workshop">Талдауға дайындал →</a></div></div><div class="grid3"><article class="card"><small>ҒАЛАМДЫҚ МӘНМӘТІН</small><h3>Уақыт пен кеңістіктегі бағдар</h3><p>Балалық мекен, естелік және ұрпақтар сабақтастығы.</p></article><article class="card"><small>НЕГІЗГІ КОНЦЕПЦИЯ</small><h3>Перспектива</h3><p>Бала көзі мен ересек баяндаушының қабылдауы.</p></article><article class="card"><small>ПӘНДІК КОНЦЕПЦИЯЛАР</small><h3>Мінез · Көзқарас</h3><p>Сөз бен әрекет адамның құндылықтарын қалай ашады?</p></article></div><div class="section-head"><h2>Оқырманнан зерттеушіге</h2><span class="tag">6 сабақ</span></div>${list()}<div class="grid2"><article class="card"><h3>Зерттеу сұрақтары</h3><p><b>Деректік:</b> Бауыржанға кімдер, қандай дәстүрлер арқылы тәрбие береді?</p><p><b>Концептуалдық:</b> Естелік баяндаушының көзқарасын қалай ашады?</p><p><b>Пікірталастық:</b> Дәстүрді сақтау оны өзгеріссіз қайталау ма?</p></article><article class="card"><h3>Оқу дағдылары</h3><p><b>Сыни ойлау:</b> түсіндірулерді дәлелмен салыстыр.</p><p><b>Коммуникация:</b> пікірді әдеби терминдермен жеткіз.</p><p><b>Өзін-өзі басқару:</b> кері байланыстан кейін жауапты түзет.</p></article></div><p class="notice">Жауаптарың осы ашық бетте сақталады. Бетті жаңартпас бұрын көшірмесін жүктеп ал. Мұғалімге автоматты түрде жіберілмейді.</p><button class="secondary" data-action="export">Жауаптарды жүктеу</button>`;}
function read(arg){const split=BOOK.paragraphs.findIndex(p=>p.trim()==='2-бөлім');if(arg!==undefined&&Number(arg)>=0)state.part=Number(arg)>=split?2:1;const start=state.part===1?2:split,end=state.part===1?split:BOOK.paragraphs.length;return head('02 · МӘТІНДІ ОҚУ','Ұшқан ұя','Бауыржан Момышұлы. Мұғалім ұсынған нұсқадағы екі бөлім.')+`<div class="tabs">${[1,2].map(n=>`<button class="${state.part===n?'selected':''}" data-action="part" data-n="${n}">${n}-бөлім</button>`).join('')}</div><div class="callout"><b>Оқу миссиясы</b><p>${state.part===1?'Кейіпкер мінезін танытатын бір әрекет пен бір сөзді таңда. Олар бірін-бірі қалай толықтырады?':'Бала қабылдауы мен ересек баяндаушының бағасын ажырат. Дәстүр туралы ойға ұласатын тұсты тап.'}</p></div><div class="reading">${BOOK.paragraphs.slice(start,end).map((p,i)=>/^\d-бөлім/.test(p.trim())?`<h2 id="p${i+start}">${esc(p)}</h2>`:`<p id="p${i+start}" class="${/^[*\s]+$/.test(p)?'break':''}">${esc(p)}</p>`).join('')}</div><p class="source-note">Дереккөз: «Ұшқан ұя мәтіні.docx». Түпнұсқадағы емле мен сөз қолданысы сақталған.</p><section class="card">${field('reading','Оқырман күнделігі: дәйексөз және оның мағынасы')}<button class="primary" data-action="review" data-id="reading">Кері байланыс алу</button>${box('reading')}</section><div class="actions"><a class="button" href="#lessons">Сабақтарға өту →</a><a class="button secondary" href="#quiz">Мазмұнды тексеру</a></div>`;}
function lesson(arg){const i=Number(arg),l=lessons[i];if(arg===undefined||!l)return head('03 · ЗЕРТТЕУ САБАҚТАРЫ','Алты қадам.<br><em>Бір тұтас талдау.</em>','Оқы → таңда → талда → кері байланыс ал → түзет.')+list();return head(`03 · САБАҚ ${i+1} / 6`,l.title,l.goal)+`<div class="callout"><b>Алдымен оқы</b><p>${l.read}</p>${link(l.anchor)}</div><p class="question">${l.inquiry}</p><section class="card"><div class="step-badge">1 · МӘТІНДІ ТҮСІН</div><h3>${l.q}</h3>${l.options.map((o,n)=>`<button class="choice ${state.answers[i]===n?'chosen':''}" data-action="lesson-answer" data-i="${i}" data-n="${n}">${String.fromCharCode(65+n)}. ${o}</button>`).join('')}${box('choice-'+i)}</section><section class="card" style="margin-top:20px"><div class="step-badge">2 · ДӘЛЕЛМЕН ТАЛДА</div>${field('lesson-'+i,l.prompt)}<button class="primary" data-action="review" data-id="lesson-${i}">Кері байланыс алу</button>${box('lesson-'+i)}<details><summary>Талдау бағыты мен үлгі</summary><p class="answer-model">${l.model}</p><p class="hint">Бұл — ықтимал түсіндіру. Өзге тұжырым да мәтінмен негізделсе орынды.</p></details></section><section class="card" style="margin-top:20px"><div class="step-badge">3 · ОЙЫҢДЫ ҚАЙТА ҚАРА</div>${field('reflect-'+i,l.reflect,'Тұжырымың және оны негіздейтін дәлел...',3)}<button class="secondary" data-action="reflection" data-id="reflect-${i}">Рефлексияға кері байланыс</button>${box('reflect-'+i)}</section><div class="actions"><button class="primary" data-action="complete" data-i="${i}">${state.done.has(i)?'Сабақ аяқталды ✓':'Сабақты аяқтау'}</button><a class="button secondary" href="${i<5?'#lessons/'+(i+1):'#workshop'}">${i<5?'Келесі сабақ':'Талдау шеберханасы'} →</a></div>${box('complete-'+i)}<p class="notice">Еркін жауапқа автоматты кері байланыс — құрылымдық бағдар. Ол ойдың дұрыстығын немесе тіл сауаттылығын толық бағаламайды. А және Д деңгейлерін мұғалім белгілейді.</p>`;}
function games(){let html=head('04 · ОЙЫН АЛАҢЫ','Дәлелді тап.<br><em>Байланысты аш.</em>','Дұрыс жауаптың қандай сөзге не әрекетке сүйенетінін түсіндір.')+`<div class="tabs">${[['match','Кейіпкерді таны'],['sequence','Оқиға тізбегі'],['device','Тіл детективі']].map(([id,t])=>`<button class="${state.game===id?'selected':''}" data-action="game" data-id="${id}">${t}</button>`).join('')}</div>`;if(state.game==='match')return html+`<section class="card"><h2>Кім қандай әрекет жасады?</h2><p>Әрекеттер бір реттен қолданылады.</p>${matches.map(([name],i)=>`<div class="match-row"><label for="match${i}">${name}</label><select id="match${i}" data-match="${i}"><option value="">Әрекетті таңда</option>${[2,4,0,3,1].map(n=>`<option value="${n}" ${state.match[i]===String(n)?'selected':''}>${matches[n][1]}</option>`).join('')}</select></div>`).join('')}<div class="actions"><button class="primary" data-action="match-check">Сәйкестікті тексеру</button></div>${box('match')}</section>`;if(state.game==='sequence')return html+`<section class="card"><h2>Кешірімге апарған төрт қадам</h2><p>Оқиғаларды жоғары-төмен батырмаларымен ретте.</p>${state.sequence.map((v,i)=>`<div class="sequence-row"><b>${i+1}</b><span>${events[v]}</span><button aria-label="${i+1}-оқиғаны жоғары жылжыту" data-action="move" data-i="${i}" data-n="-1" ${i===0?'disabled':''}>↑</button><button aria-label="${i+1}-оқиғаны төмен жылжыту" data-action="move" data-i="${i}" data-n="1" ${i===3?'disabled':''}>↓</button></div>`).join('')}<div class="actions"><button class="primary" data-action="sequence-check">Ретті тексеру</button></div>${box('sequence')}${link('Текебайдың бақталасы')}</section>`;return html+`<section class="card"><h2>Сөздің астарындағы тәсіл</h2><p>Құралды таңда. Кері байланыстан оның әсерін оқы.</p>${devices.map(([quote],i)=>`<div class="match-row"><label for="device${i}">${quote}</label><select id="device${i}" data-device="${i}"><option value="">Тәсілді таңда</option>${['Теңеу','Қайталау','Метафора','Кейіптеу'].map(t=>`<option ${state.device[i]===t?'selected':''}>${t}</option>`).join('')}</select></div>`).join('')}<div class="actions"><button class="primary" data-action="device-check">Тәсілдерді тексеру</button></div>${box('device')}<p class="source-note">Карточкалардағы үзінді сөздерінің тыныс белгілері біріздендірілген. Толық мәтін оқу бөлімінде берілген.</p></section>`;}
function quiz(){if(state.qi>=questions.length){const score=state.quiz.filter((a,i)=>a===questions[i][2]).length;return head('05 · МАЗМҰН ТЕСТІ','Нәтижеңді зертте',`${score} / ${questions.length} дұрыс. Бұл — мазмұн көрсеткіші, А немесе Д бағасы емес.`)+`<div class="callout">${score===questions.length?'Мазмұнды нақты таныдың. Енді деректердің автор идеясын қалай ашатынын талда.':'Қателескен сұрақтарды түсіндірмемен салыстырып, эпизодтарды қайта оқы.'}</div>${questions.map((q,i)=>`<details ${state.quiz[i]!==q[2]?'open':''}><summary>${state.quiz[i]===q[2]?'✓':'↻'} ${i+1}. ${q[0]}</summary><p>Сенің жауабың: ${q[1][state.quiz[i]]}</p><p><b>Дұрыс жауап:</b> ${q[1][q[2]]}</p><p>${q[3]}</p>${link(q[4])}</details>`).join('')}<div class="actions"><button class="primary" data-action="quiz-reset">Қайта орындау</button><a class="button secondary" href="#workshop">Талдауға өту →</a></div>`;}const q=questions[state.qi],a=state.quiz[state.qi];return head('05 · МАЗМҰН ТЕСТІ','Оқығаның есіңде ме?')+`<section class="card"><div class="quiz-meta"><span>Сұрақ ${state.qi+1} / ${questions.length}</span><span>Екі бөлім бойынша</span></div><div class="meter"><span style="width:${100*state.qi/questions.length}%"></span></div><h2 class="question">${q[0]}</h2>${q[1].map((o,n)=>`<button class="choice ${a!==undefined?(n===q[2]?'correct':n===a?'wrong':''):''}" data-action="quiz-answer" data-n="${n}" ${a!==undefined?'disabled':''}>${String.fromCharCode(65+n)}. ${o}${a!==undefined&&n===q[2]?' ✓':''}</button>`).join('')}${a!==undefined?`<div class="feedback ${a===q[2]?'':'error'}" role="status"><b>${a===q[2]?'Дұрыс.':'Жауабыңды қайта қара.'}</b><p>${q[3]}</p>${link(q[4])}</div><button class="primary" data-action="quiz-next">${state.qi===questions.length-1?'Нәтижені көру':'Келесі сұрақ'} →</button>`:'<p class="hint">Жауаптан кейін түсіндірме ашылады.</p>'}</section>`;}
const excerpt=()=>`<div class="reading">${BOOK.excerpt.map(p=>`<p>${esc(p)}</p>`).join('')}</div><p class="source-note">Дайындық үзіндісі: 2-бөлімдегі «Қайран, балалық-ай десеңші!» деп басталатын қатар тұрған 3 абзац. Мұғалім ұсынған мәтіннен өзгеріссіз алынды.</p>`;
const stepCard=s=>`<section class="card" style="margin:20px 0"><h2>${s[1]}</h2>${field('work-'+s[0],s[2])}<button class="primary" data-action="review" data-id="work-${s[0]}">Кері байланыс алу</button>${box('work-'+s[0])}<details><summary>Бағыттаушы тірек</summary><p>${s[3]}</p></details></section>`;
function workshop(){return head('06 · ТАЛДАУ ШЕБЕРХАНАСЫ','Дәйексөзден<br><em>дәйекті ойға</em>','Үзіндіні оқы. Талдау бөліктерін әзірлеп, әрқайсысына кері байланыс ал.')+idea()+excerpt()+`<div class="callout"><b>Талдау формуласы</b><p>Тұжырым → дәйексөз → тәсіл мен мағына → автор мақсаты → оқырманға әсер.</p><p class="hint">Автор мақсатын мәтінге сүйенген пайым ретінде түсіндір: «... аңғартады», «... деп түсіндіруге болады».</p></div>${steps.slice(0,2).map(stepCard).join('')}<section class="card"><div class="step-badge">КӨРКЕМ ТІЛ · А КРИТЕРИЙІ</div><h2>Үш құрал — үш дәлел</h2><p>Үш түрлі құрал таңда. Әрқайсысында дәйексөз, дұрыс термин, мақсат және әсер болсын.</p>${[0,1,2].map(i=>`${field('tool-'+i,`${i+1}-көркемдеуіш құрал`,'Дәйексөз: ...\nҚұрал: ...\nАвтор мақсаты: ...\nОқырманға әсері: ...',4)}<button class="secondary" data-action="review" data-id="tool-${i}">Осы талдауға кері байланыс</button>${box('tool-'+i)}`).join('')}<details><summary>Үш құралға тірек</summary><p><b>Метафора:</b> «желі — жібек» — әлемнің жұмсақтығын сездіреді.</p><p><b>Теңеу:</b> «жас баланың көз жасындай» — табиғат пен адам сезімін жақындастырады.</p><p><b>Кейіптеу:</b> табиғаттың «елжірей қарап», «аймалап әлдилеуі» — балаға әлемнің мейірімді көрінуін жеткізеді.</p><p>Әр дәлелді толық контексте тексеріп, өз сөзіңмен дамыт.</p></details></section>${steps.slice(2).map(stepCard).join('')}<section class="card"><h2>Д · Тілді қолдану</h2><p>«Автор әдемі сөздер қолданған, сондықтан мәтін жақсы» деген жалпы сөйлемді әдеби терминмен және нақты әсермен толықтыр.</p>${field('language','Сөйлемді жетілдір','Автор ... тәсілін қолданып, ... әсерін тудырады.',3)}<button class="primary" data-action="review" data-id="language">Тілдік бағдар алу</button>${box('language')}<details><summary>Үлгіні салыстыр</summary><p>Автор «желі — жібек» метафорасы арқылы баланың дүниені нәзік әрі мейірімді қабылдауын бейнелейді.</p><p>Термин дәлдігін, сөйлем құрылысын және тыныс белгілерін тексер.</p></details></section><div class="actions"><button class="primary" data-action="assemble">Жоспарымды тұтас мәтінге жинау →</button><button class="secondary" data-action="export">Жауаптарды жүктеу</button></div>${box('assemble')}`;}
const requirements=()=>`<ol><li><b>Кіріспе:</b> автор мен шығарма атауын анықта; тақырып пен идеяны түсіндір.</li><li><b>Негізгі бөлім:</b> әдеби тәсілдер мен қолданылу мақсатын талда; кемінде 3 көркемдеуіш құралды тауып, автор мақсатын аш; салт-дәстүрдің маңызы мен оқырманға әсерін түсіндір.</li><li><b>Қорытынды:</b> ойды зерттеу идеясымен байланыстырып, автор шеберлігіне баға бер.</li></ol><p><b>Пішімі:</b> біртұтас мәтін. Көлемі мен орындау уақыты берілген құжатта белгіленбеген; оларды мұғалім нақтылайды.</p>`;
function finalView(){return head('07 · ҚОРЫТЫНДЫ ЖҰМЫСҚА ДАЙЫНДЫҚ','Өз талдауыңды жаз','А — Талдау және Д — Тілді қолдану. Әр критерийдің ең жоғары деңгейі — 8.')+`<details><summary>Тапсырма талаптарын ашу</summary>${requirements()}</details><details><summary>Дайындық үзіндісін ашу</summary>${excerpt()}</details><p class="hint">Бұл — жаттығу нұсқасы. Нақты қорытынды жұмыстың үзіндісін және өткізу тәртібін мұғалім белгілейді.</p>${idea()}${field('final','Біртұтас талдау мәтіні','Кіріспе, негізгі бөлім және қорытындыны ой сабақтастығын сақтап жаз...',18)}<div class="wordcount" id="wordcount">${wc(state.drafts.final||'')} сөз · сөз саны бағаға айналдырылмайды</div><div class="actions"><button class="primary" data-action="final-review">Құрылымды тексеру</button><button class="secondary" data-action="export">Жұмысымды жүктеу</button></div>${box('final')}<section class="card"><h2>Тапсырар алдындағы өзіндік тексеру</h2><div class="checklist">${checks.map((t,i)=>`<label><input type="checkbox" data-check="${i}" ${state.checks[i]?'checked':''}><span>${t}</span></label>`).join('')}</div><button class="primary" data-action="self-review">Өзіндік бағалауды түйіндеу</button>${box('self')}<p class="notice">Белгіленген тармақтар — сенің өзіндік бағалауың. Автоматты тексеру А немесе Д ұпайын қоймайды; мазмұн сапасы мен тіл сауаттылығын мұғалім бағалайды.</p></section><div class="grid2"><section class="card"><h3>А · Талдау</h3><p>Дәйексөздер пікіріңді дәлелдей ме? Тәсілдердің автор мақсаты мен оқырманға әсерін аштың ба?</p></section><section class="card"><h3>Д · Тілді қолдану</h3><p>Терминдер дәл ме? Стиль талдауға сай ма? Сөйлем, грамматика, емле мен тыныс белгілері түсінуге кедергі келтірмей ме?</p></section></div><section class="card"><h2>Өзара кері байланыс</h2><p>Жұбың бір мықты тұсты дәлелмен көрсетсін және бір нақты жақсарту қадамын ұсынсын. Жауапты түзетіп, өзгерісті түсіндір.</p>${field('peer','Жұбымның пікірі және мен енгізген өзгеріс','Сәтті тұсы: ...\nДәлелі: ...\nКелесі қадам: ...\nМен өзгерттім: ...',4)}<button class="secondary" data-action="reflection" data-id="peer">Кері байланысты нақтылау</button>${box('peer')}</section><div class="actions"><a class="button secondary" href="#criteria">Толық дескрипторлар →</a><a class="text-link" href="#workshop">Шеберханаға оралу</a></div>`;}
function criteria(){const tables=BOOK.rubrics.filter(t=>t.length>=4);return head('БАҒАЛАУ БАҒДАРЫ','А және Д критерийлері','Дескрипторлар мұғалім ұсынған құжаттан алынды.')+`<section class="card"><h2>Қорытынды жұмыс: үзінді талдау</h2>${requirements()}</section><div class="callout"><b>Критерийді қалай қолданасың?</b><p>Өз талдауыңнан дәлел көрсет. Оны дескриптормен салыстыр. Жоғары деңгей үшін түсіндірудің тереңдігі мен тілдің дәлдігіне назар аудар.</p></div>${tables.map((t,i)=>`<h2 style="margin-top:32px">${i===0?'А · Талдау':'Д · Тілді қолдану'}</h2><div class="rubric-wrap"><table><thead><tr>${t[0].map(c=>`<th>${esc(c)}</th>`).join('')}</tr></thead><tbody>${t.slice(1).map(r=>`<tr>${r.map(c=>`<td>${esc(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`).join('')}<p class="source-note">Дереккөз: «Критертйлер.docx». Дескриптор мәтіні түпнұсқадағыдай берілген. Юнит компоненттері мұғалімнің тапсырмасы бойынша енгізілді.</p><p class="notice">А критерийіндегі мәтіндер байланысын жаттықтыру үшін өзге эпизодпен салыстыруға болады. Қорытынды жұмыста салыстырудың міндеттілігі мұғалімнің нақты нұсқаулығымен анықталады.</p><a class="button" href="#final">Талдауыма оралу →</a>`;}
function review(id){const v=(state.drafts[id]||'').trim();if(wc(v)<8)return fb(id,'<b>Алдымен ойыңды дамыт.</b><p>Бір толық тұжырым мен мәтіндік дәлел жаз. Содан кейін құрылымдық бағдар аласың.</p>',true);const quote=/[«“"]/.test(v),term=/метафор|теңеу|кейіптеу|эпитет|қайталау|диалог|баяндаушы|қарама-қарсы/i.test(v),effect=/оқырман|әсер|сезім|сезін|аңғар|мақсат|көрсет|таныт/i.test(v);let next='Дәйексөзді түпнұсқамен салыстыр. Тұжырымыңды қалай дәлелдейтінін және оқырманға әсерін түсіндір.';if(id.startsWith('lesson-'))next=lessons[Number(id.split('-')[1])].next;if(id.startsWith('work-'))next=steps.find(s=>'work-'+s[0]===id)?.[3]||next;if(id==='language')next='Жалпы бағалауыш сөзді нақты терминмен алмастыр. Сөйлемді дауыстап оқып, ой байланысы мен тыныс белгілерін тексер.';return fb(id,`<b>Құрылымдық бағдар</b><p>${wc(v)} сөз жазылды. Бұл көлем көрсеткіші, сапа бағасы емес.</p><p><b>Байқалған белгілер:</b> ${quote?'дәйексөз тырнақшасы бар':'дәйексөз тырнақшасы табылмады'}; ${term?'талдау термині кездесті':'әдеби терминді нақтыла'}; ${effect?'әсерді түсіндіретін сөз кездесті':'әсер мен мақсатты ашатын сөйлем қос'}.</p><p><b>Келесі қадам:</b> ${next}</p><p class="mini">Бұл сөздік белгілерге сүйенген тексеру ойдың дұрыстығын не тереңдігін растамайды. Жауапты тірекпен және А, Д дескрипторларымен салыстырып түзет.</p>`);}
function reflection(id){if(wc(state.drafts[id]||'')<6)return fb(id,'<b>Пікіріңді нақтыла.</b><p>Бір тұжырым және оны негіздейтін себеп жаз.</p>',true);return fb(id,`<b>Ойыңды қайта тексер</b><p>${id==='peer'?'Пікірде нақты сөйлем көрсетілген бе? Ұсыныс орындалатын әрекет пе? Өзгерістің талдауды қалай жақсартқанын түсіндір.':'Пікіріңді мәтіндік дәлелмен байланыстырдың ба? Басқа көзқарас болуы мүмкін екенін ескеріп, таңдауыңды түсіндір.'}</p><p><b>Келесі қадам:</b> «Себебі мәтінде ...» немесе «Келесіде ... өзгертемін» деп нақтылау қос.</p>`);}
function finalReview(){const v=state.drafts.final||'';if(wc(v)<20)return fb('final','<b>Талдауды алдымен жаз.</b><p>Автор, шығарма, тақырып пен идеядан баста. Кейін дәйексөздерді талда.</p>',true);const terms=['метафора','теңеу','кейіптеу','эпитет','қайталау','гипербола'].filter(t=>v.toLowerCase().includes(t));return fb('final',`<b>Алдын ала құрылымдық тексеру</b><ul><li>${v.trim().split(/\n\s*\n/).length} абзац анықталды (бос жол арқылы бөлінген).</li><li>${terms.length} түрлі құрал атауы кездесті${terms.length?': '+terms.join(', '):''}.</li><li>${/[«“"]/.test(v)?'Дәйексөз тырнақшасы бар; мәтінге дәлдігін тексер.':'Қысқа дәйексөз келтіріп, тырнақшамен белгіле.'}</li></ul><p><b>Келесі қадам:</b> ${terms.length<3?'Кемінде 3 көркемдеуіш құралдың талданғанын тексер.':'Әр құралдың дұрыс қолданылғанын тексер.'} Әрқайсысына дәлел, мақсат және әсер жаз. Қорытындыда ұлттық тәрбие мен рухани даму байланысын аш.</p><p class="mini">Терминді табу оның дұрыс қолданылғанын білдірмейді. Бұл тексеру мазмұнға, грамматикаға немесе А/Д деңгейіне баға бермейді.</p>`);}
function label(id){if(id==='final')return 'Біртұтас талдау';if(id==='reading')return 'Оқырман күнделігі';if(id==='language')return 'Тілді қолдану';if(id==='peer')return 'Өзара кері байланыс';if(id.startsWith('lesson-'))return lessons[+id.split('-')[1]]?.title||id;if(id.startsWith('reflect-'))return 'Рефлексия: '+(lessons[+id.split('-')[1]]?.title||id);if(id.startsWith('tool-'))return 'Көркемдеуіш құрал '+(+id.split('-')[1]+1);return steps.find(s=>'work-'+s[0]===id)?.[1]||id;}
function exportWork(){const lines=['ҰШҚАН ҰЯ — ТӘРБИЕ МЕН САЛТ ДӘСТҮР','9-сынып · А: Талдау · Д: Тілді қолдану',IDEA,...Object.entries(state.drafts).filter(([,v])=>v.trim()).map(([k,v])=>label(k)+'\n'+v),'КЕРІ БАЙЛАНЫС',...Object.entries(state.fb).map(([k,v])=>{const el=document.createElement('div');el.innerHTML=v;return label(k)+'\n'+el.textContent;}),'ӨЗІНДІК ТЕКСЕРУ',...checks.map((t,i)=>(state.checks[i]?'[✓] ':'[ ] ')+t),`Аяқталған сабақтар: ${state.done.size}/6`,`Тест: ${state.quiz.filter((a,i)=>a===questions[i][2]).length} дұрыс / ${state.quiz.length} жауап берілген`,'Автоматты кері байланыс — қорытынды баға емес.'];const blob=new Blob(['\ufeff'+lines.join('\n\n')],{type:'text/plain;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='Ұшқан ұя — менің талдауым.txt';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);state.saved=true;}
function render(){let [view,arg]=(location.hash.slice(1)||'home').split('/');const views={home,read:()=>read(arg),lessons:()=>lesson(arg),games,quiz,workshop,final:finalView,criteria};if(!views[view])view='home';$('#view').innerHTML=views[view]();document.querySelectorAll('[data-view]').forEach(a=>{const on=a.dataset.view===view;a.classList.toggle('active',on);if(on)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('#progress-bar').style.width=100*state.done.size/6+'%';$('#progress-text').textContent=`${state.done.size} / 6 сабақ аяқталды`;document.title=$('h1').textContent+' · Ұшқан ұя';if(view==='read'&&arg!==undefined)requestAnimationFrame(()=>$('#p'+Number(arg))?.scrollIntoView());}
document.addEventListener('input',e=>{const id=e.target.dataset.draft;if(id){state.drafts[id]=e.target.value;state.saved=false;if(id==='final'&&$('#wordcount'))$('#wordcount').textContent=wc(e.target.value)+' сөз · сөз саны бағаға айналдырылмайды';}});
document.addEventListener('change',e=>{const d=e.target.dataset;if(d.match!==undefined){state.match[d.match]=e.target.value;fb('match','');}if(d.device!==undefined){state.device[d.device]=e.target.value;fb('device','');}if(d.check!==undefined)state.checks[d.check]=e.target.checked;});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const d=b.dataset,i=Number(d.i),n=Number(d.n);switch(d.action){
case 'part':state.part=n;history.replaceState(null,'','#read');render();window.scrollTo(0,0);break;
case 'lesson-answer':{const l=lessons[i];state.answers[i]=n;state.fb['choice-'+i]=`<b>${n===l.answer?'Дұрыс пайым.':'Мәтіндегі дәлелді қайта қара.'}</b><p>${l.explain}</p><p><b>Келесі қадам:</b> түсіндіруді дәйексөзбен бекіт.</p>`;render();break;}
case 'review':review(d.id);break;case 'reflection':reflection(d.id);break;
case 'complete':if(state.answers[i]===undefined||wc(state.drafts['lesson-'+i]||'')<8||wc(state.drafts['reflect-'+i]||'')<6||!state.fb['lesson-'+i]||!state.fb['reflect-'+i])fb('complete-'+i,'<b>Оқу қадамдарын толықтыр.</b><p>Сұраққа жауап бер, талдау мен рефлексия жаз, әрқайсысына кері байланыс ал.</p>',true);else{state.done.add(i);state.fb['complete-'+i]='<b>Оқу қадамдары орындалды.</b><p>Бұл — қатысу белгісі. Кері байланыстың бір ұсынысын жауабыңа енгізіп, келесі сабаққа өт.</p>';render();}break;
case 'game':state.game=d.id;render();break;
case 'match-check':{const score=matches.filter((x,j)=>state.match[j]===String(j)).length;fb('match',`<b>${score} / 5 сәйкестік дұрыс.</b><ul>${matches.map(([name,act],j)=>`<li>${state.match[j]===String(j)?'✓':'↻'} <b>${name}:</b> ${act}</li>`).join('')}</ul><p><b>Келесі қадам:</b> қатені түзетіп, қайта тексер. Әр әрекеттің мінезді қалай ашатынын ойлан.</p>`,score<5);break;}
case 'move':{const j=i+n;if(j>=0&&j<4){[state.sequence[i],state.sequence[j]]=[state.sequence[j],state.sequence[i]];state.fb.sequence='';render();}break;}
case 'sequence-check':{const ok=state.sequence.every((v,j)=>v===j);fb('sequence',ok?'<b>Оқиға желісі дұрыс!</b><p>Қызбалық → әкенің сыны → өкініш → кешірім. Келесі қадам: әкенің бағасы ұлының көзқарасына қалай әсер еткенін түсіндір.</p>':'<b>Ретті қайта тексер.</b><p>Алдымен Серкебай ауылға барады. Одан кейін әкесі ісін құптамайды. Үшінші күнгі өкініш кешірім сұраудан бұрын болады. Карточкаларды түзетіп, қайта тексер.</p>',!ok);break;}
case 'device-check':{const score=devices.filter((x,j)=>state.device[j]===x[1]).length;fb('device',`<b>${score} / 4 тәсіл дұрыс.</b><ul>${devices.map((x,j)=>`<li>${state.device[j]===x[1]?'✓':'↻'} <b>${x[0]} — ${x[1]}.</b> ${x[2]}</li>`).join('')}</ul><p><b>Келесі қадам:</b> бір құралдың автор мақсаты мен оқырманға әсерін шеберханада талда.</p>`,score<4);break;}
case 'quiz-answer':if(state.quiz[state.qi]===undefined){state.quiz[state.qi]=n;render();}break;
case 'quiz-next':if(state.quiz[state.qi]!==undefined){state.qi++;render();}break;
case 'quiz-reset':state.quiz=[];state.qi=0;render();break;
case 'assemble':{const ids=['work-intro','work-perspective','tool-0','tool-1','tool-2','work-tradition','work-conclusion'];if(ids.some(k=>!(state.drafts[k]||'').trim())){fb('assemble','<b>Жоспарды толықтыр.</b><p>Кіріспе, екі перспектива, үш құрал, дәстүр және қорытынды жауаптарын жаз.</p>',true);break;}if((state.drafts.final||'').trim()){fb('assemble','<b>Бұрын жазылған талдауың бар.</b><p>Ол сақталды. Жоспарды жүктеп алып, қажетті тұстарын өзің енгіз: бұрынғы мәтіннің үстінен жазылмайды.</p>');break;}state.drafts.final=ids.map(k=>state.drafts[k]).join('\n\n');state.saved=false;location.hash='final';break;}
case 'final-review':finalReview();break;
case 'self-review':{const missing=checks.filter((t,j)=>!state.checks[j]);fb('self',`<b>${10-missing.length} / 10 тармақ белгіленді.</b><p>${missing.length?'<b>Келесі қадам:</b> '+missing[0]+' Осы талапты мәтіндегі сөйлеммен тексер.':'Әр белгіге жұмысыңнан дәлел көрсетіп, мәтінді дауыстап оқы. Соңғы тілдік түзетулерді енгіз.'}</p><p class="mini">Бұл — өзіндік тексеру, мұғалім бағасы емес.</p>`);break;}
case 'export':exportWork();break;
}});
window.addEventListener('hashchange',()=>{render();if(!location.hash.startsWith('#read/')){window.scrollTo(0,0);$('#main').focus({preventScroll:true});}});
window.addEventListener('beforeunload',e=>{if(!state.saved&&Object.values(state.drafts).some(v=>v.trim())){e.preventDefault();e.returnValue='';}});
render();
if(document.modelContext?.registerTool){const life=new AbortController();for(const t of [{name:'get_learning_progress',title:'Оқу барысын оқу',description:'Read lesson and quiz progress without changing answers.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(input){if(!input||typeof input!=='object'||Object.keys(input).length)throw Error('Expected empty object');return {completedLessons:[...state.done].map(i=>i+1),quizAnswered:state.quiz.length,quizTotal:questions.length};}},{name:'open_learning_section',title:'Оқу бөлімін ашу',description:'Open a section without submitting or grading work.',inputSchema:{type:'object',properties:{section:{type:'string',enum:['home','read','lessons','games','quiz','workshop','final','criteria']}},required:['section'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||Object.keys(input).length!==1||!['home','read','lessons','games','quiz','workshop','final','criteria'].includes(input.section))throw Error('Invalid section');history.replaceState(null,'','#'+input.section);render();return {section:input.section,visible:!!$('#view').textContent};}}]){try{Promise.resolve(document.modelContext.registerTool(t,{signal:life.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>life.abort(),{once:true});}
